namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string OfficeLocation { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
    public Instructor Instructor { get; set; } = null!;
    public bool IsFeatured { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events, societies, and civilizations." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Bio = "Dr. Chen specializes in artificial intelligence and machine learning with over 15 years of research experience. She has published extensively in top-tier conferences and journals.", Email = "achen@university.edu", OfficeLocation = "Science Building 301" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor", Bio = "Dr. Martinez focuses on discrete mathematics and combinatorics. He is known for his engaging teaching style and mentorship of undergraduate researchers.", Email = "rmartinez@university.edu", OfficeLocation = "Math Hall 205" },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Professor", Bio = "Dr. Johnson is a renowned physicist working in quantum mechanics. She leads the university's quantum computing initiative.", Email = "sjohnson@university.edu", OfficeLocation = "Physics Lab 102" },
            new() { Id = 4, Name = "Dr. Michael Brown", Title = "Assistant Professor", Bio = "Dr. Brown specializes in modern American literature and creative writing. He is an award-winning novelist and poet.", Email = "mbrown@university.edu", OfficeLocation = "Humanities 410" },
            new() { Id = 5, Name = "Dr. Emily Davis", Title = "Professor", Bio = "Dr. Davis is a historian of medieval Europe with expertise in cultural exchange between civilizations.", Email = "edavis@university.edu", OfficeLocation = "History Hall 303" },
            new() { Id = 6, Name = "Dr. James Wilson", Title = "Associate Professor", Bio = "Dr. Wilson specializes in software engineering and distributed systems. He has industry experience at leading technology companies.", Email = "jwilson@university.edu", OfficeLocation = "Science Building 215" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A foundational course covering programming fundamentals, data types, control structures, and basic algorithms. Students will learn to write programs in Python and develop computational thinking skills.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Building 101", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures and Algorithms", Description = "In-depth study of data structures including trees, graphs, hash tables, and heaps. Covers algorithm design techniques such as divide-and-conquer, dynamic programming, and greedy algorithms.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Building 205", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[5], IsFeatured = true, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS 450", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search algorithms, knowledge representation, machine learning fundamentals, natural language processing, and computer vision.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Science Building 301", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 44 },
            new() { Id = 4, Code = "MATH 201", Title = "Calculus II", Description = "Continuation of single-variable calculus covering techniques of integration, sequences, series, and introduction to multivariable calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Math Hall 101", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 62 },
            new() { Id = 5, Code = "MATH 310", Title = "Discrete Mathematics", Description = "Logic, set theory, combinatorics, graph theory, and number theory. Essential for computer science students.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Hall 205", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = true, MaxEnrollment = 50, CurrentEnrollment = 38 },
            new() { Id = 6, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, waves, and thermodynamics. Covers Newton's laws, energy conservation, rotational dynamics, and wave phenomena.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Physics Lab 100", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 85 },
            new() { Id = 7, Code = "PHYS 401", Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave-particle duality, Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Physics Lab 102", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = true, MaxEnrollment = 30, CurrentEnrollment = 25 },
            new() { Id = 8, Code = "ENG 201", Title = "Creative Writing", Description = "Workshop-based course in fiction and poetry writing. Students will develop original works, participate in peer review, and study craft elements.", Credits = 3, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Humanities 201", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = false, MaxEnrollment = 25, CurrentEnrollment = 24 },
            new() { Id = 9, Code = "ENG 350", Title = "Modern American Literature", Description = "Survey of American literature from 1900 to present, including works by Fitzgerald, Hemingway, Morrison, and contemporary authors.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", Location = "Humanities 305", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 28 },
            new() { Id = 10, Code = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from ancient times to 1500 CE, covering major political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "History Hall 101", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = false, MaxEnrollment = 90, CurrentEnrollment = 72 },
            new() { Id = 11, Code = "HIST 320", Title = "Medieval Europe", Description = "In-depth study of European civilization from the fall of Rome to the Renaissance, including feudalism, the Church, and cultural exchange.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "History Hall 303", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 31 },
            new() { Id = 12, Code = "CS 201", Title = "Software Engineering", Description = "Principles of software development including requirements analysis, design patterns, testing, version control, and agile methodologies.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Science Building 210", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[5], IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 47 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }
}

